import pyomo.environ as pyo

DATA = {
    "products": ["P1", "P2"],
    "stages": ["S1", "S2"],
    "rate": [[2, 3], [3, 2]],       # rate[p][s]
    "profit": [10, 20],             # profit per ton
    "commit": [1, 2],               # min tons per week
    "market": [5, 4],               # max tons per week
    "avail": [10, 8],               # hours available per week per stage
}


def build_model(data=None):
    d = data or DATA

    products = list(d["products"])
    stages = list(d["stages"])
    profit = d["profit"]
    commit = d["commit"]
    market = d["market"]
    rate = d["rate"]
    avail = d["avail"]

    model = pyo.ConcreteModel()

    # Sets
    model.P = pyo.Set(initialize=products)
    model.S = pyo.Set(initialize=stages)

    def profit_of(p):
        return profit[products.index(p)]

    def commit_of(p):
        return commit[products.index(p)]

    def market_of(p):
        return market[products.index(p)]

    def rate_of(p, s):
        return rate[products.index(p)][stages.index(s)]

    def avail_of(s):
        return avail[stages.index(s)]

    # Variables: tons produced/sold, bounded by commit and market limits
    def x_bounds(m, p):
        return (commit_of(p), market_of(p))

    model.x = pyo.Var(model.P, within=pyo.NonNegativeReals, bounds=x_bounds)

    # Objective: maximize total profit
    def obj_rule(m):
        return sum(profit_of(p) * m.x[p] for p in m.P)

    model.obj = pyo.Objective(expr=obj_rule(model), sense=pyo.maximize)

    # Constraint: lower (commit) limit for each product
    def commit_rule(m, p):
        return m.x[p] >= commit_of(p)

    model.commit_limit = pyo.Constraint(model.P, rule=commit_rule)

    # Constraint: upper (market) limit for each product
    def market_rule(m, p):
        return m.x[p] <= market_of(p)

    model.market_limit = pyo.Constraint(model.P, rule=market_rule)

    # Constraint: hours used in each stage cannot exceed hours available
    def stage_rule(m, s):
        return sum(m.x[p] / rate_of(p, s) for p in m.P) <= avail_of(s)

    model.stage_capacity = pyo.Constraint(model.S, rule=stage_rule)

    return model


