import pyomo.environ as pyo

DATA = {
    "products": ["P1", "P2"],
    "stages": ["S1", "S2"],
    "rate": [[2, 3], [3, 2]],       # rate[p][s]: tons per hour of product p at stage s
    "profit": [10, 20],             # profit per ton for each product
    "commit": [1, 2],               # minimum tons per week for each product
    "market": [5, 4],               # maximum tons per week for each product
    "avail": [10, 8],               # hours available per week at each stage
}


def build_model(data=None):
    d = data or DATA

    products = d["products"]
    stages = d["stages"]

    # Map product -> index and stage -> index for the 2D rate list
    p_idx = {p: i for i, p in enumerate(products)}
    s_idx = {s: j for j, s in enumerate(stages)}

    rate = {(p, s): d["rate"][p_idx[p]][s_idx[s]]
            for p in products for s in stages}
    profit = {p: d["profit"][p_idx[p]] for p in products}
    commit = {p: d["commit"][p_idx[p]] for p in products}
    market = {p: d["market"][p_idx[p]] for p in products}
    avail = {s: d["avail"][s_idx[s]] for s in stages}

    model = pyo.ConcreteModel()

    model.Products = pyo.Set(initialize=products)
    model.Stages = pyo.Set(initialize=stages)

    # Decision variable: tons of each product to produce
    def tons_bounds(m, p):
        return (commit[p], market[p])

    model.tons = pyo.Var(
        model.Products,
        domain=pyo.NonNegativeReals,
        bounds=tons_bounds,
    )

    # Objective: maximize total profit
    def obj_rule(m):
        return sum(profit[p] * m.tons[p] for p in m.Products)

    model.obj = pyo.Objective(expr=obj_rule(model), sense=pyo.maximize)

    # Stage capacity: hours used = tons / rate <= available hours
    def stage_capacity_rule(m, s):
        return sum(m.tons[p] / rate[(p, s)] for p in m.Products) <= avail[s]

    model.stage_capacity = pyo.Constraint(
        model.Stages, rule=stage_capacity_rule
    )

    return model

import pyomo.environ as pyo

DATA = {
    "products": ["P1", "P2"],
    "stages": ["S1", "S2"],
    "rate": [[2, 3], [3, 2]],
    "profit": [10, 20],
    "commit": [1, 2],
    "market": [5, 4],
    "avail": [10, 8],
}


def build_model(data=None):
    d = data or DATA

    products = d["products"]
    stages = d["stages"]

    # Map product -> index and stage -> index for 2D rate lookup
    prod_idx = {p: i for i, p in enumerate(products)}
    stage_idx = {s: j for j, s in enumerate(stages)}

    profit = {p: d["profit"][prod_idx[p]] for p in products}
    commit = {p: d["commit"][prod_idx[p]] for p in products}
    market = {p: d["market"][prod_idx[p]] for p in products}
    avail = {s: d["avail"][stage_idx[s]] for s in stages}
    # hours per ton of product p in stage s = 1 / rate[p][s]
    hours_per_ton = {
        (p, s): 1.0 / d["rate"][prod_idx[p]][stage_idx[s]]
        for p in products
        for s in stages
    }

    model = pyo.ConcreteModel()

    model.Products = pyo.Set(initialize=products)
    model.Stages = pyo.Set(initialize=stages)

    # Decision variable: tons produced/sold of each product
    def prod_bounds(m, p):
        return (commit[p], market[p])

    model.production = pyo.Var(
        model.Products,
        domain=pyo.NonNegativeReals,
        bounds=prod_bounds,
    )

    # Objective: maximize total profit
    def obj_rule(m):
        return sum(profit[p] * m.production[p] for p in m.Products)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Constraint: hours used in each stage <= hours available
    def stage_capacity_rule(m, s):
        return sum(hours_per_ton[(p, s)] * m.production[p] for p in m.Products) <= avail[s]

    model.stage_capacity = pyo.Constraint(model.Stages, rule=stage_capacity_rule)

    return model


